'use client'

import * as React from 'react'
import { cva, type VariantProps } from 'class-variance-authority'
import { Xmark } from 'iconoir-react'
import { cn } from '@/lib/utils'
import { Button } from '@/registry/satin/ui/button'

/**
 * Card, 1:1 with the uiKit `Card` set (1122:20156): bg/card, 1px border/default, radius-2xl (16),
 * no shadow, 405 wide by default. Three stacked sections with no gap between them:
 *
 * - header: title in Label/lg (14/14 medium), description in text/sm muted, 2px apart.
 *   Padding 16 / 16 / 0 on md, 12 / 12 / 0 on sm (no bottom padding: the body's top padding
 *   is the space under it).
 * - body (children): 16 padding on md, 12 on sm, children 8 apart.
 * - footer: same padding as the body; its items sit in a row, 8 apart.
 *
 * `onClose` adds a tertiary 28px icon button 7px from the top-right corner.
 */
const cardVariants = cva(
  'sa:relative sa:flex sa:w-[405px] sa:max-w-full sa:flex-col sa:overflow-clip sa:rounded-2xl sa:border sa:border-border-default sa:bg-bg-card',
  {
    variants: {
      size: {
        md: 'sa:[--card-pad:calc(var(--sa-spacing)*4)]',
        sm: 'sa:[--card-pad:calc(var(--sa-spacing)*3)]',
      },
    },
    defaultVariants: { size: 'md' },
  },
)

export interface CardProps extends Omit<React.ComponentProps<'div'>, 'title'>, VariantProps<typeof cardVariants> {
  title?: React.ReactNode
  description?: React.ReactNode
  footer?: React.ReactNode
  /** Shows the close button. */
  onClose?: () => void
  /** Accessible name of the close button. */
  closeLabel?: string
}

export function Card({
  className,
  size,
  title,
  description,
  footer,
  onClose,
  closeLabel = 'Close',
  children,
  ...props
}: CardProps) {
  const titleId = React.useId()
  const hasHeader = title != null || description != null
  return (
    <div
      data-slot="card"
      role={title != null ? 'group' : undefined}
      aria-labelledby={title != null ? titleId : undefined}
      className={cn(cardVariants({ size }), className)}
      {...props}
    >
      {hasHeader && (
        <div data-slot="card-header" className={cn('sa:flex sa:flex-col sa:gap-0.5 sa:px-(--card-pad) sa:pt-(--card-pad)', onClose && 'sa:pr-10')}>
          {title != null && (
            <div id={titleId} className="sa:text-base sa:leading-[14px] sa:font-medium sa:tracking-normal sa:text-text-default">
              {title}
            </div>
          )}
          {description != null && <p className="sa:text-body sa:text-text-muted">{description}</p>}
        </div>
      )}
      {children != null && (
        <div data-slot="card-body" className="sa:flex sa:flex-col sa:gap-2 sa:p-(--card-pad)">
          {children}
        </div>
      )}
      {footer != null && (
        <div data-slot="card-footer" className="sa:flex sa:items-center sa:gap-2 sa:p-(--card-pad)">
          {footer}
        </div>
      )}
      {onClose && (
        <Button
          variant="tertiary"
          iconOnly
          aria-label={closeLabel}
          onClick={onClose}
          className="sa:absolute sa:top-[7px] sa:right-[7px]"
        >
          <Xmark aria-hidden />
        </Button>
      )}
    </div>
  )
}

export { cardVariants }
